    h, w = len(grid), len(grid[0])

    result = [[0]*w for _ in range(h)]

    for r in range(h):
        # Find all marker positions (value = 1) in this row
        markers_row = {c for c in range(w) if grid[r][c] == 1}

        pw = len(template)
        max_valid_start = w - pw

